      const g=(gd.eye||0)+(gd.verbal||0)+(gd.motor||0);
      const sev=g<=8?'TBI חמור':g<=12?'TBI בינוני':'תקין';
      const sevCol=g<=8?'var(--re-hi)':g<=12?'var(--ye)':'var(--gr)';
      return `<div style="font-size:10px;color:var(--t3);padding:2px">GCS: <b style="color:${sevCol}">${g||'—'}/15</b> ${g?`<span style="color:${sevCol}">(${sev})</span>`:''}<span style="color:var(--t4);margin-inline-start:6px">· המחשבון המלא למטה</span></div>`;
