function _markWriteError(){
  const now=Date.now();
  window._writeErrTimes=(window._writeErrTimes||[]).filter(t=>now-t<25000);
  window._writeErrTimes.push(now);
  if(window._writeErrTimes.length>=2) window._lastWriteError=now;
  updateOfflineBanner();
}
function updateOfflineBanner(){
  const el=document.getElementById('offline-banner');if(!el)return;
  const recentErr=window._lastWriteError && (Date.now()-window._lastWriteError<20000);
  el.style.display = recentErr ? 'block' : 'none';
}
