function _showConsentGate(onOk){
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML=`<div style="max-width:480px;background:var(--bg);border:2px solid var(--re);border-radius:16px;padding:20px;direction:rtl;font-family:var(--f)">
    <div style="font-size:18px;font-weight:900;color:var(--re);margin-bottom:12px">⚕️ איסוף מידע רפואי רגיש</div>
    <div style="font-size:13px;color:var(--t2);line-height:1.6;margin-bottom:14px">
      אתה עומד להזין נתוני נפגע (שם, מ.א/ת.ז, פציעות, סימנים חיוניים).<br><br>
      <strong>בסיס חוקי:</strong> טיפול רפואי בשעת חירום — סעיף 15 לחוק זכויות החולה התשנ״ו-1996.<br>
      <strong>עיבוד:</strong> המידע מסונכרן עם Google Firebase ומשותף עם חברי הצוות המאושרים.<br>
      <strong>שמירה:</strong> על פי חוק הגנת הפרטיות תשמ״א-1981 (תיקון 13) ותקנות הגנת הפרטיות (אבטחת מידע) תשע״ז-2017.<br><br>
      <strong>חובה על המזין:</strong> להגביל מספר השדות המזוהים למינימום הנדרש לטיפול ולהימנע מהעברת ייצואים לאפיקים לא-מאובטחים.
    </div>
    <button id="sh-consent-ok" style="width:100%;padding:14px;border-radius:12px;background:var(--re);color:#fff;border:none;font-weight:800;font-size:15px;cursor:pointer;font-family:var(--f);min-height:48px">אישור — ממשיך לטיפול חירום</button>
    <button id="sh-consent-cancel" style="width:100%;margin-top:8px;padding:12px;border-radius:12px;background:none;border:1px solid var(--sep);color:var(--t3);font-size:13px;cursor:pointer;font-family:var(--f);min-height:44px">ביטול</button>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector('#sh-consent-ok').onclick=()=>{_grantConsent();ov.remove();onOk&&onOk();};
  ov.querySelector('#sh-consent-cancel').onclick=()=>{ov.remove();};
}
