async function quickTriageCasualty(color){
  if(!_incidentAlertId){toast('אין אירוע פעיל',false);return;}
  const name=document.getElementById('mci-rapid-name')?.value||_saltIdType+' '+(_saltIdCounter[_saltIdType]+1);
  _saltIdCounter[_saltIdType]++;
  const tc=color||null;
  const data={name,triageColor:tc||'',moi:'',injuries:[],treatments:[],injuredRegions:[],evacStatus:'waiting',
    xabcde:{x:{tourniquets:[],pressureDressings:[],hemostatic:[],woundPacking:[]},a:{status:'',interventions:[]},b:{respiratoryRate:null,tubeThora:null,oxygen:null},c:{pulseCharacter:'',capRefill:null,ivAccess:[],fluids:[]},d:{avpu:'',gcs:null,pupils:{left:{size:3,reactive:true},right:{size:3,reactive:true}},motorFunction:{}},e:{hypothermiaPrevention:'',medications:[],notes:''}},
    timeline:[],vitalsHistory:[],burnPercentage:0,evacPriority:tc==='red'?'immediate':tc==='yellow'?'urgent':'routine',
    reportedBy:curUser?.uid||'',reportedByName:curUser?.displayName||''};
  const uidSuf=(curUser?.uid||'anon').replace(/[^A-Za-z0-9]/g,'').slice(0,6)||'anon';
  const id='cas_'+Date.now().toString(36)+'_'+uidSuf;
  const emoji=tc?({red:'🔴',yellow:'🟡',green:'🟢',gray:'🔘',black:'⬛'})[tc]:'❓';
  try{
    if(_canWriteCloud()){
      data.timestamp=window.FB.serverTimestamp();
      await window.FB.setDoc(window.FB.doc(window.FB.fbDb,'teams',curTeamId,'alerts',_incidentAlertId,'casualties',id),data);
      mciToast(`${emoji} ${escapeHtml(name)}${tc?'':' — לחץ לקבוע טריאז׳'}`,async()=>{try{await window.FB.deleteDoc(window.FB.doc(window.FB.fbDb,'teams',curTeamId,'alerts',_incidentAlertId,'casualties',id));if(tc)_mciRapidCounts[tc]--;renderIncidentPage();}catch(e){}});
    } else {
      // Offline — push to local store, flag for drain.
      _upsertOfflineCasualty({...data,_docId:id,id:id,_pendingOffline:true,timestamp:{toDate:()=>new Date()},_localUpdatedAt:new Date().toISOString()});
      mciToast(`📴 ${emoji} ${escapeHtml(name)} — ישלח כשיחזור חיבור`,()=>{_removeOfflineCasualty(id);if(tc)_mciRapidCounts[tc]--;renderIncidentPage();});
    }
    if(tc)_mciRapidCounts[tc]=(_mciRapidCounts[tc]||0)+1;
    _mciRapidName='';
    if(navigator.vibrate)navigator.vibrate(15);
    renderIncidentPage();
  }catch(e){
    if(e && e.code==='permission-denied')toast('אין הרשאה',false);
    else if(e && e.code==='unavailable')toast('ייסונכרן כשיחזור חיבור',false);
    else toast('שגיאה בהוספת נפגע',false);
  }
}
