  ov.setAttribute('role','dialog');ov.setAttribute('aria-label','9-Line MEDEVAC');
  let inner='<div style="font-size:18px;font-weight:900;color:#e74c3c;text-align:center;margin-bottom:12px">📋 9-Line MEDEVAC</div>';
