      h+=`<div style="flex:1"><label style="font-size:10px;color:var(--t3);display:block;margin-bottom:2px">🛏 שכיבה</label><input class="fi" type="number" min="0" max="20" placeholder="שכ״ב" value="${v.litter||''}" oninput="_mciVehicles[${i}].litter=parseInt(this.value)||null;_syncMciVehicles()" style="font-size:12px;padding:8px;min-height:40px;width:100%;text-align:center"></div>`;
      h+=`</div>`;
