      h+=`<button onclick="removeMciVehicle(${i})" style="background:none;border:none;color:var(--t4);font-size:11px;cursor:pointer;font-family:var(--f);margin-top:4px;padding:8px;min-height:36px">🗑 הסר רכב</button>`;
